using System;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
using CodexWatchdog;
class BootstrapEngineTests {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static string file;static DateTime stamp=new DateTime(2026,10,25,6,0,0,DateTimeKind.Utc);
 static void Add(string type,object payload){File.AppendAllText(file,Json.Serialize(new{timestamp=stamp.ToString("o"),type=type,payload=payload})+"\n");stamp=stamp.AddMilliseconds(1);}
 static void Fill(string id){Add("session_meta",new{id=id,originator="Codex Desktop",source="vscode"});Add("event_msg",new{type="task_started",turn_id=id,root_turn_id=id});for(int i=0;i<160;i++)Add("response_item",new{type="reasoning",text=new String('x',8192)});Add("event_msg",new{type="task_complete",turn_id=id,root_turn_id=id});}
 static void Check(bool b,string m){if(!b){Console.WriteLine("FAIL: "+m);Environment.Exit(1);}}
 static void Main(){string home=Path.Combine(Path.GetTempPath(),"bootstrap-engine-"+Guid.NewGuid());string dir=Path.Combine(home,"sessions/2026/10/25");Directory.CreateDirectory(dir);try{
 file=Path.Combine(dir,"rollout-history.jsonl");Fill("history");using(var source=new CodexSessionSource(home)){source.MaxPollBytes=1024*1024;source.SelectedSourceId="history";var engine=new WatchEngine(new WatchSettings());DateTime now=stamp;
 var first=source.Poll(now);Check(!first.Snapshots.Single().IsAvailable&&!first.Snapshots.Single().IsCaughtUp,"partial historical baseline unavailable for arming");Check(first.Snapshots.Single().Detail=="正在同步历史运行记录"&&first.Health=="正在同步历史运行记录","bootstrap health means syncing not failure");Check(engine.Update(first.Snapshots,now).Count==0,"first partial history silent");var second=source.Poll(now.AddSeconds(1));Check(second.Snapshots.Single().IsAvailable&&!second.Snapshots.Single().IsGenerating&&second.Snapshots.Single().Transitions.Count==0,"finished historical baseline stopped and silent");Check(engine.Update(second.Snapshots,now.AddSeconds(1)).Count==0,"historical finish not armed");Check(engine.Update(source.Poll(now.AddSeconds(7)).Snapshots,now.AddSeconds(7)).Count==0,"historical split read never rings after settle");}
 using(var source=new CodexSessionSource(home)){source.MaxPollBytes=1024*1024;DateTime baseline=stamp;source.Poll(baseline);source.Poll(baseline.AddSeconds(1));file=Path.Combine(dir,"rollout-live.jsonl");stamp=baseline.AddSeconds(2);Fill("live");source.SelectedSourceId="live";var engine=new WatchEngine(new WatchSettings());var first=source.Poll(baseline.AddSeconds(11));var pending=first.Snapshots.Single(x=>x.SourceId=="live");Check(!pending.IsAvailable&&pending.Transitions.Count==0,"new live chain withheld during partial baseline");Check(engine.Update(first.Snapshots,baseline.AddSeconds(11)).Count==0,"partial live baseline quiet");var second=source.Poll(baseline.AddSeconds(12));var ready=second.Snapshots.Single(x=>x.SourceId=="live");Check(ready.IsAvailable&&ready.Transitions.Count==2&&ready.Transitions[0].Kind==MonitorTransitionKind.Working&&ready.Transitions[1].Kind==MonitorTransitionKind.Completed,"real after-start live chain delivered after bootstrap");Check(engine.Update(second.Snapshots,baseline.AddSeconds(12)).Count==0,"live completion settles");Check(engine.Update(source.Poll(baseline.AddSeconds(18)).Snapshots,baseline.AddSeconds(18)).Count==1,"real live stop rings once after settle");}
 Console.WriteLine("Bootstrap + engine split-budget tests passed");}finally{Directory.Delete(home,true);}}
}
